def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with current working directory if path is relative
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]  # Skip empty first element
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Parse target components
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative target - relative to directory containing the link
                current = candidate.rsplit('/', 1)[0]
                if not current:
                    current = '/'
                target_components = target.split('/')

            # Insert target components at current position in components list
            components = components[:i] + target_components + components[i:]
            i = 0  # Restart from beginning with new components
        else:
            # Not a symlink, just move to this path
            current = candidate

    # Remove trailing slash, except for root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

